1: /**
2:  * FORK & SHARE — Home Page Script
3:  * Handles hero recipe search routing, featured recipe category filtering,
4:  * and saved-recipe bookmarking in localStorage.
5:  */
6: 
7: document.addEventListener("DOMContentLoaded", function () {
8:   var STORAGE_KEY = "forkAndShare_savedRecipes";
9: 
10:   initHeroSearch();
11:   initFeaturedFilters();
12:   initSaveButtons(STORAGE_KEY);
13: });
14: 
15: /**
16:  * Routes non-empty hero searches to the Explore Recipes page with ?q=...
17:  */
18: function initHeroSearch() {
19:   var form = document.getElementById("home-search-form");
20:   var input = document.getElementById("home-search-input");
21:   var feedback = document.getElementById("home-search-feedback");
22: 
23:   if (!form || !input) {
24:     return;
25:   }
26: 
27:   form.addEventListener("submit", function (event) {
28:     event.preventDefault();
29:     var query = input.value.trim();
30: 
31:     if (!query) {
32:       if (feedback) {
33:         feedback.textContent = "Please enter an ingredient or recipe name to search.";
34:       }
35:       input.focus();
36:       return;
37:     }
38: 
39:     if (feedback) {
40:       feedback.textContent = "";
41:     }
42: 
43:     window.location.href = "pages/explore.html?q=" + encodeURIComponent(query);
44:   });
45: 
46:   input.addEventListener("input", function () {
47:     if (feedback && feedback.textContent) {
48:       feedback.textContent = "";
49:     }
50:   });
51: }
52: 
53: /**
54:  * Filters the Featured Recipes grid by category button selection.
55:  */
56: function initFeaturedFilters() {
57:   var filterButtons = document.querySelectorAll("[data-filter]");
58:   var recipeCards = document.querySelectorAll("#featured-grid .recipe-card");
59:   var statusEl = document.getElementById("filter-status");
60: 
61:   if (!filterButtons.length || !recipeCards.length) {
62:     return;
63:   }
64: 
65:   filterButtons.forEach(function (button) {
66:     button.addEventListener("click", function () {
67:       var selectedFilter = button.getAttribute("data-filter");
68:       var visibleCount = 0;
69: 
70:       filterButtons.forEach(function (btn) {
71:         var isCurrent = btn === button;
72:         btn.classList.toggle("is-selected", isCurrent);
73:         btn.setAttribute("aria-pressed", String(isCurrent));
74:       });
75: 
76:       recipeCards.forEach(function (card) {
77:         var categories = (card.getAttribute("data-categories") || "").split(/\s+/);
78:         var matches = selectedFilter === "all" || categories.indexOf(selectedFilter) !== -1;
79:         card.hidden = !matches;
80:         if (matches) {
81:           visibleCount += 1;
82:         }
83:       });
84: 
85:       if (statusEl) {
86:         var label = button.textContent.trim();
87:         statusEl.textContent =
88:           "Showing " +
89:           visibleCount +
90:           " " +
91:           (visibleCount === 1 ? "recipe" : "recipes") +
92:           (selectedFilter === "all" ? "." : " in " + label + ".");
93:       }
94:     });
95:   });
96: }
97: 
98: /**
99:  * Restores and toggles saved recipe state in localStorage.
100:  */
101: function initSaveButtons(storageKey) {
102:   var saveButtons = document.querySelectorAll("[data-save-recipe]");
103:   if (!saveButtons.length) {
104:     return;
105:   }
106: 
107:   var savedIds = loadSavedIds(storageKey);
108: 
109:   saveButtons.forEach(function (button) {
110:     var recipeId = button.getAttribute("data-save-recipe");
111:     setSaveButtonState(button, savedIds.indexOf(recipeId) !== -1);
112: 
113:     button.addEventListener("click", function () {
114:       var isCurrentlySaved = savedIds.indexOf(recipeId) !== -1;
115: 
116:       if (isCurrentlySaved) {
117:         savedIds = savedIds.filter(function (id) {
118:           return id !== recipeId;
119:         });
120:       } else {
121:         savedIds.push(recipeId);
122:       }
123: 
124:       persistSavedIds(storageKey, savedIds);
125:       setSaveButtonState(button, !isCurrentlySaved);
126:     });
127:   });
128: }
129: 
130: function setSaveButtonState(button, isSaved) {
131:   button.classList.toggle("is-saved", isSaved);
132:   button.setAttribute("aria-pressed", String(isSaved));
133:   button.textContent = isSaved ? "Saved" : "Save";
134: }
135: 
136: function loadSavedIds(storageKey) {
137:   try {
138:     var raw = window.localStorage.getItem(storageKey);
139:     var parsed = raw ? JSON.parse(raw) : [];
140:     return Array.isArray(parsed) ? parsed : [];
141:   } catch (error) {
142:     return [];
143:   }
144: }
145: 
146: function persistSavedIds(storageKey, ids) {
147:   try {
148:     window.localStorage.setItem(storageKey, JSON.stringify(ids));
149:   } catch (error) {
150:     /* Ignore storage quota or privacy-mode errors gracefully */
151:   }
152: }

